import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.find.js";
/* eslint-disable */
import { format_Date } from "@/JsonFiles/DateFormate.js";
import { portal_event_list_with_particular_users } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import EventRegistration from "@/components/EventApp/EventPopups/EventRegistration.vue";
import SnackBar from "@/components/SnackBar.vue";
export default {
  components: {
    SnackBar,
    EventRegistration
  },
  data: () => ({
    adminAppExists: false,
    SnackBarComponent: {},
    rowInfo: {},
    componet_check: 0,
    all_event_Items: "ALL",
    fixed: true,
    event_Items: [{
      title: "All",
      value: "ALL"
    }, {
      title: "Completed",
      value: "COMPLETED"
    }, {
      title: "Upcoming",
      value: "UPCOMING"
    }, {
      title: "Live",
      value: "LIVE"
    }],
    register_check: null,
    tableLoading: false,
    displayEvents: false,
    tableData: [],
    headers: [{
      title: "Event Name",
      key: "event_name",
      sortable: false
    }, {
      title: "Description",
      key: "event_description",
      sortable: false
    }, {
      title: "Date",
      key: "from_date",
      sortable: false
    }, {
      title: "Status",
      key: "event_progress_status",
      sortable: false
    }, {
      title: "Actions",
      key: "actions",
      sortable: false
    }],
    currentPage: 1,
    itemsPerPage: 20,
    windowHeight: 0
  }),
  created() {
    this.fetch_admin_apps();
    this.windowHeight = window.innerHeight - 250;
    this.list_users();
  },
  computed: {
    totalItems() {
      return this.tableData.length;
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.tableData.slice(start, end);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  watch: {
    all_event_Items() {
      this.currentPage = 1;
    },
    currentPage() {
      // Scroll to top when page changes
      const table = document.querySelector(".dtwidth");
      if (table) table.scrollIntoView({
        behavior: "smooth",
        block: "start"
      });
    }
  },
  methods: {
    open_settings() {
      this.$router.push("/home/EventPlanner");
    },
    fetch_admin_apps() {
      const userObj = this.$store.getters.GetUserObj;

      // Check if userObj and admin_apps exist
      if (!userObj || !userObj.admin_apps || !Array.isArray(userObj.admin_apps)) {
        this.adminAppExists = false;
        return;
      }
      const adminExists = userObj.admin_apps.find(app => app.dashboard_unique_type === "EVENTS_ADMINS");

      // Check if adminExists is defined before accessing its properties
      if (!adminExists) {
        this.adminAppExists = false;
        return;
      }
      if (adminExists.is_visible === false) {
        this.adminAppExists = false;
        return;
      }
      this.adminAppExists = adminExists && (adminExists.app_usage_level === "WEB_PHONE_ONLY" || adminExists.app_usage_level === "WEB_ONLY") && adminExists.is_dashboard_admin === true;
    },
    back_call() {
      this.$router.push({
        name: "UserlevelApp"
      });
    },
    get_date(date) {
      return format_Date(date / 1000);
    },
    pop_up(val) {
      if (val == 0) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Email ID aldery Registered",
          timeout: 5000,
          Top: true
        };
      } else if (val == 1) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Registration is closed",
          timeout: 5000,
          Top: true
        };
      }
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    async success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.displayEvents = false;
      this.list_users();
    },
    visbility_action(info, displaytype) {
      this.componet_check = 1;
      this.rowInfo = {};
      this.displayEvents = true;
      this.rowInfo = {
        info: info,
        displaytype: displaytype
      };
    },
    async list_users() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(portal_event_list_with_particular_users, {
          input: {
            organization_id: data.organization.organization_id,
            event_progress_status: this.all_event_Items,
            nextToken: null,
            limit: 100
          }
        }));
        var check_status = JSON.parse(result.data.portal_event_list_with_particular_users).Status;
        if (check_status == "SUCCESS") {
          var response = JSON.parse(result.data.portal_event_list_with_particular_users).workflow;
          for (let i = 0; i < response.length; i++) {
            if (response[i].register_users.indexOf(data.user.user_email_id) > -1) {
              response[i].register_check = true;
            } else {
              response[i].register_check = false;
            }
          }
          this.tableData = response;
          this.tableLoading = false;
          // this.updatePageItems(); // This line is removed as per the edit hint
        } else {
          this.tableLoading = false;
          this.tableData = [];
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: JSON.parse(result.data.portal_event_list_with_particular_users).Message,
            timeout: 2000,
            Top: true
          };
        }
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
        this.tableLoading = false;
      }
    },
    handleSortChange(headers) {
      // Implement sorting logic based on the headers
      // console.log("Sorting by:", headers);
    }
  }
};
